    28→namespace Nethermind.State
    29→{
    30→    public class WorldState : IWorldState, IPreBlockCaches
    31→    {
    32→        internal readonly StateProvider _stateProvider;
    33→        internal readonly PersistentStorageProvider _persistentStorageProvider;
    34→        private readonly TransientStorageProvider _transientStorageProvider;
    35→        private readonly ITrieStore _trieStore;
    36→        private bool _isInScope = false;
    37→        private readonly ILogger _logger;
    38→        private PreBlockCaches? PreBlockCaches { get; }
    39→        public bool IsWarmWorldState { get; }
    40→
    41→        public Hash256 StateRoot
    42→        {
    43→            get
    44→            {
    45→                GuardInScope();
    46→                return _stateProvider.StateRoot;
    47→            }
    48→            private set
    49→            {
    50→                _stateProvider.StateRoot = value;
    51→                _persistentStorageProvider.StateRoot = value;
    52→            }
    53→        }
    54→
    55→        public WorldState(ITrieStore trieStore, IKeyValueStoreWithBatching? codeDb, ILogManager? logManager)
    56→            : this(trieStore, codeDb, logManager, null, null)
    57→        {
    58→        }
    59→
    60→        internal WorldState(
    61→            ITrieStore trieStore,
    62→            IKeyValueStoreWithBatching? codeDb,
    63→            ILogManager? logManager,
    64→            StateTree? stateTree = null,
    65→            IStorageTreeFactory? storageTreeFactory = null,
    66→            PreBlockCaches? preBlockCaches = null,
    67→            bool populatePreBlockCache = true)
    68→        {
    69→            PreBlockCaches = preBlockCaches;
    70→            IsWarmWorldState = !populatePreBlockCache;
    71→            _trieStore = trieStore;
    72→            _stateProvider = new StateProvider(trieStore.GetTrieStore(null), codeDb, logManager, stateTree, PreBlockCaches?.StateCache, populatePreBlockCache);
    73→            _persistentStorageProvider = new PersistentStorageProvider(trieStore, _stateProvider, logManager, storageTreeFactory, PreBlockCaches?.StorageCache, populatePreBlockCache);
    74→            _transientStorageProvider = new TransientStorageProvider(logManager);
    75→            _logger = logManager.GetClassLogger<WorldState>();
    76→        }
    77→
    78→        public WorldState(ITrieStore trieStore, IKeyValueStoreWithBatching? codeDb, ILogManager? logManager, PreBlockCaches? preBlockCaches, bool populatePreBlockCache = true)
    79→            : this(trieStore, codeDb, logManager, null, preBlockCaches: preBlockCaches, populatePreBlockCache: populatePreBlockCache)
    80→        {
    81→        }
    82→
    83→        [MethodImpl(MethodImplOptions.AggressiveInlining)]
    84→        private void GuardInScope()
    85→        {
    86→            if (!_isInScope) ThrowOutOfScope();
    87→        }
    88→
    89→        [MethodImpl(MethodImplOptions.AggressiveInlining)]
    90→        private void DebugGuardInScope()
    91→        {
    92→#if DEBUG
    93→            if (!_isInScope) ThrowOutOfScope();
    94→#endif
    95→        }
    96→
    97→        [StackTraceHidden, DoesNotReturn]
    98→        private void ThrowOutOfScope()
    99→        {
   100→            throw new InvalidOperationException($"{nameof(IWorldState)} must only be used within scope");
   101→        }
   102→
   103→        public Account GetAccount(Address address)
   104→        {
   105→            DebugGuardInScope();
   106→            return _stateProvider.GetAccount(address);
   107→        }
   108→
   109→        bool IAccountStateProvider.TryGetAccount(Address address, out AccountStruct account)
   110→        {
   111→            account = _stateProvider.GetAccount(address).ToStruct();
   112→            return !account.IsTotallyEmpty;
   113→        }
   114→
   115→        public bool IsContract(Address address)
   116→        {
   117→            DebugGuardInScope();
   118→            return _stateProvider.IsContract(address);
   119→        }
   120→
   121→        public byte[] GetOriginal(in StorageCell storageCell)
   122→        {
   123→            DebugGuardInScope();
   124→            return _persistentStorageProvider.GetOriginal(storageCell);
   125→        }
   126→        public ReadOnlySpan<byte> Get(in StorageCell storageCell)
   127→        {
   128→            DebugGuardInScope();
   129→            return _persistentStorageProvider.Get(storageCell);
   130→        }
   131→        public void Set(in StorageCell storageCell, byte[] newValue)
   132→        {
   133→            DebugGuardInScope();
   134→            _persistentStorageProvider.Set(storageCell, newValue);
   135→        }
   136→        public ReadOnlySpan<byte> GetTransientState(in StorageCell storageCell)
   137→        {
   138→            DebugGuardInScope();
   139→            return _transientStorageProvider.Get(storageCell);
   140→        }
   141→        public void SetTransientState(in StorageCell storageCell, byte[] newValue)
   142→        {
   143→            DebugGuardInScope();
   144→            _transientStorageProvider.Set(storageCell, newValue);
   145→        }
   146→        public void Reset(bool resetBlockChanges = true)
   147→        {
   148→            DebugGuardInScope();
   149→            _stateProvider.Reset(resetBlockChanges);
   150→            _persistentStorageProvider.Reset(resetBlockChanges);
   151→            _transientStorageProvider.Reset(resetBlockChanges);
   152→        }
   153→        public void WarmUp(AccessList? accessList)
   154→        {
   155→            if (accessList?.IsEmpty == false)
   156→            {
   157→                foreach ((Address address, AccessList.StorageKeysEnumerable storages) in accessList)
   158→                {
   159→                    bool exists = _stateProvider.WarmUp(address);
   160→                    foreach (UInt256 storage in storages)
   161→                    {
   162→                        _persistentStorageProvider.WarmUp(new StorageCell(address, in storage), isEmpty: !exists);
   163→                    }
   164→                }
   165→            }
   166→        }
   167→
   168→        public void WarmUp(Address address) => _stateProvider.WarmUp(address);
   169→        public void ClearStorage(Address address)
   170→        {
   171→            DebugGuardInScope();
   172→            _persistentStorageProvider.ClearStorage(address);
   173→            _transientStorageProvider.ClearStorage(address);
   174→        }
   175→        public void RecalculateStateRoot()
   176→        {
   177→            DebugGuardInScope();
   178→            _stateProvider.RecalculateStateRoot();
   179→        }
   180→        public void DeleteAccount(Address address)
   181→        {
   182→            DebugGuardInScope();
   183→            _stateProvider.DeleteAccount(address);
   184→        }
   185→        public void CreateAccount(Address address, in UInt256 balance, in UInt256 nonce = default)
   186→        {
   187→            DebugGuardInScope();
   188→            _stateProvider.CreateAccount(address, balance, nonce);
   189→        }
   190→        public bool InsertCode(Address address, in ValueHash256 codeHash, ReadOnlyMemory<byte> code, IReleaseSpec spec, bool isGenesis = false)
   191→        {
   192→            DebugGuardInScope();
   193→            return _stateProvider.InsertCode(address, codeHash, code, spec, isGenesis);
   194→        }
   195→        public void AddToBalance(Address address, in UInt256 balanceChange, IReleaseSpec spec)
   196→        {
   197→            DebugGuardInScope();
   198→            _stateProvider.AddToBalance(address, balanceChange, spec);
   199→        }
   200→        public bool AddToBalanceAndCreateIfNotExists(Address address, in UInt256 balanceChange, IReleaseSpec spec)
   201→        {
   202→            DebugGuardInScope();
   203→            return _stateProvider.AddToBalanceAndCreateIfNotExists(address, balanceChange, spec);
   204→        }
   205→        public void SubtractFromBalance(Address address, in UInt256 balanceChange, IReleaseSpec spec)
   206→        {
   207→            DebugGuardInScope();
   208→            _stateProvider.SubtractFromBalance(address, balanceChange, spec);
   209→        }
   210→        public void UpdateStorageRoot(Address address, Hash256 storageRoot)
   211→        {
   212→            DebugGuardInScope();
   213→            _stateProvider.UpdateStorageRoot(address, storageRoot);
   214→        }
   215→        public void IncrementNonce(Address address, UInt256 delta)
   216→        {
   217→            DebugGuardInScope();
   218→            _stateProvider.IncrementNonce(address, delta);
   219→        }
   220→        public void DecrementNonce(Address address, UInt256 delta)
   221→        {
   222→            DebugGuardInScope();
   223→            _stateProvider.DecrementNonce(address, delta);
   224→        }
   225→
   226→        public void CommitTree(long blockNumber)
   227→        {
   228→            DebugGuardInScope();
   229→            using (IBlockCommitter committer = _trieStore.BeginBlockCommit(blockNumber))
   230→            {
   231→                _persistentStorageProvider.CommitTrees(committer);
   232→                _stateProvider.CommitTree();
   233→            }
   234→            _persistentStorageProvider.StateRoot = _stateProvider.StateRoot;
   235→        }
   236→
   237→        public UInt256 GetNonce(Address address)
   238→        {
   239→            DebugGuardInScope();
   240→            return _stateProvider.GetNonce(address);
   241→        }
   242→
   243→        public IDisposable BeginScope(BlockHeader? baseBlock)
   244→        {
   245→            if (_isInScope) throw new InvalidOperationException("Cannot create nested worldstate scope.");
   246→            _isInScope = true;
   247→
   248→            if (_logger.IsTrace) _logger.Trace($"Beginning WorldState scope with baseblock {baseBlock?.ToString(BlockHeader.Format.Short) ?? "null"} with stateroot {baseBlock?.StateRoot?.ToString() ?? "null"}.");
   249→
   250→            StateRoot = baseBlock?.StateRoot ?? Keccak.EmptyTreeHash;
   251→            IDisposable trieStoreCloser = _trieStore.BeginScope(baseBlock);
   252→
   253→            return new Reactive.AnonymousDisposable(() =>
   254→            {
   255→                Reset();
   256→                StateRoot = Keccak.EmptyTreeHash;
   257→                trieStoreCloser.Dispose();
   258→                _isInScope = false;
   259→                if (_logger.IsTrace) _logger.Trace($"WorldState scope for baseblock {baseBlock?.ToString(BlockHeader.Format.Short) ?? "null"} closed");
   260→            });
   261→        }
   262→
   263→        public bool IsInScope => _isInScope;
