    30→namespace Nethermind.State
    31→{
    32→    internal class StateProvider
    33→    {
    34→        private static readonly UInt256 _zero = UInt256.Zero;
    35→
    36→        private readonly Dictionary<AddressAsKey, Stack<int>> _intraTxCache = new();
    37→        private readonly HashSet<AddressAsKey> _committedThisRound = new();
    38→        private readonly HashSet<AddressAsKey> _nullAccountReads = new();
    39→        // Only guarding against hot duplicates so filter doesn't need to be too big
    40→        // Note:
    41→        // False negatives are fine as they will just result in a overwrite set
    42→        // False positives would be problematic as the code _must_ be persisted
    43→        private readonly ClockKeyCacheNonConcurrent<ValueHash256> _codeInsertFilter = new(1_024);
    44→        private readonly Dictionary<AddressAsKey, ChangeTrace> _blockChanges = new(4_096);
    45→        private readonly ConcurrentDictionary<AddressAsKey, Account>? _preBlockCache;
    46→
    47→        private readonly List<Change> _keptInCache = new();
    48→        private readonly ILogger _logger;
    49→        private readonly IKeyValueStoreWithBatching _codeDb;
    50→        private Dictionary<Hash256AsKey, byte[]> _codeBatch;
    51→        private Dictionary<Hash256AsKey, byte[]>.AlternateLookup<ValueHash256> _codeBatchAlternate;
    52→
    53→        private readonly List<Change> _changes = new(Resettable.StartCapacity);
    54→        internal readonly StateTree _tree;
    55→        private readonly Func<AddressAsKey, Account> _getStateFromTrie;
    56→
    57→        private readonly bool _populatePreBlockCache;
    58→        private bool _needsStateRootUpdate;
    59→
    60→        public StateProvider(IScopedTrieStore? trieStore,
    61→            IKeyValueStoreWithBatching codeDb,
    62→            ILogManager logManager,
    63→            StateTree? stateTree = null,
    64→            ConcurrentDictionary<AddressAsKey, Account>? preBlockCache = null,
    65→            bool populatePreBlockCache = true)
    66→        {
    67→            _preBlockCache = preBlockCache;
    68→            _populatePreBlockCache = populatePreBlockCache;
    69→            _logger = logManager?.GetClassLogger<StateProvider>() ?? throw new ArgumentNullException(nameof(logManager));
    70→            _codeDb = codeDb ?? throw new ArgumentNullException(nameof(codeDb));
    71→            _tree = stateTree ?? new StateTree(trieStore, logManager);
    72→            _getStateFromTrie = address =>
    73→            {
    74→                Metrics.IncrementStateTreeReads();
    75→                return _tree.Get(address);
    76→            };
    77→        }
    78→
    79→        public void Accept<TCtx>(ITreeVisitor<TCtx> visitor, Hash256? stateRoot, VisitingOptions? visitingOptions = null) where TCtx : struct, INodeContext<TCtx>
    80→        {
    81→            ArgumentNullException.ThrowIfNull(visitor);
    82→            ArgumentNullException.ThrowIfNull(stateRoot);
    83→
    84→            _tree.Accept(visitor, stateRoot, visitingOptions);
    85→        }
    86→
    87→        public void RecalculateStateRoot()
    88→        {
    89→            _tree.UpdateRootHash();
    90→            _needsStateRootUpdate = false;
    91→        }
    92→
    93→        public Hash256 StateRoot
    94→        {
    95→            get
    96→            {
    97→                if (_needsStateRootUpdate) ThrowStateRootNeedsToBeUpdated();
    98→                return _tree.RootHash;
    99→
   100→                [DoesNotReturn, StackTraceHidden]
   101→                static void ThrowStateRootNeedsToBeUpdated() => throw new InvalidOperationException("State root needs to be updated");
   102→            }
   103→            set => _tree.RootHash = value;
   104→        }
   105→
   106→        public bool IsContract(Address address)
   107→        {
   108→            Account? account = GetThroughCache(address);
   109→            return account is not null && account.IsContract;
   110→        }
   111→
   112→        public bool AccountExists(Address address) =>
   113→            _intraTxCache.TryGetValue(address, out Stack<int> value)
   114→                ? _changes[value.Peek()]!.ChangeType != ChangeType.Delete
   115→                : GetAndAddToCache(address) is not null;
   116→
   117→        public Account GetAccount(Address address) => GetThroughCache(address) ?? Account.TotallyEmpty;
   118→
   119→        public bool IsDeadAccount(Address address)
   120→        {
   121→            Account? account = GetThroughCache(address);
   122→            return account?.IsEmpty ?? true;
   123→        }
   124→
   125→        public UInt256 GetNonce(Address address)
   126→        {
   127→            Account? account = GetThroughCache(address);
   128→            return account?.Nonce ?? UInt256.Zero;
   129→        }
   130→
   131→        public Hash256 GetStorageRoot(Address address)
   132→        {
   133→            Account? account = GetThroughCache(address);
   134→            return account is not null ? account.StorageRoot : ThrowIfNull(address);
   135→
   136→            [DoesNotReturn, StackTraceHidden]
   137→            static Hash256 ThrowIfNull(Address address)
   138→                => throw new InvalidOperationException($"Account {address} is null when accessing storage root");
   139→        }
   140→
   141→        public ref readonly UInt256 GetBalance(Address address)
   142→        {
   143→            Account? account = GetThroughCache(address);
   144→            return ref account is not null ? ref account.Balance : ref _zero;
   145→        }
   146→
   147→        public bool InsertCode(Address address, in ValueHash256 codeHash, ReadOnlyMemory<byte> code, IReleaseSpec spec, bool isGenesis = false)
   148→        {
   149→            bool inserted = false;
   150→
   151→            // Don't reinsert if already inserted. This can be the case when the same
   152→            // code is used by multiple deployments. Either from factory contracts (e.g. LPs)
   153→            // or people copy and pasting popular contracts
   154→            if (!_codeInsertFilter.Get(codeHash))
   155→            {
   156→                if (_codeBatch is null)
   157→                {
   158→                    _codeBatch = new(Hash256AsKeyComparer.Instance);
   159→                    _codeBatchAlternate = _codeBatch.GetAlternateLookup<ValueHash256>();
   160→                }
   161→                if (MemoryMarshal.TryGetArray(code, out ArraySegment<byte> codeArray)
   162→                        && codeArray.Offset == 0
   163→                        && codeArray.Count == code.Length)
   164→                {
   165→                    _codeBatchAlternate[codeHash] = codeArray.Array;
   166→                }
   167→                else
   168→                {
   169→                    _codeBatchAlternate[codeHash] = code.ToArray();
   170→                }
   171→
   172→                _codeInsertFilter.Set(codeHash);
   173→                inserted = true;
   174→            }
   175→
   176→            Account? account = GetThroughCache(address) ?? ThrowIfNull(address);
   177→            if (account.CodeHash.ValueHash256 != codeHash)
   178→            {
   179→                _needsStateRootUpdate = true;
   180→                if (_logger.IsDebug) Debug(address, codeHash, account);
   181→                Account changedAccount = account.WithChangedCodeHash((Hash256)codeHash);
   182→
   183→                PushUpdate(address, changedAccount);
   184→            }
   185→            else if (spec.IsEip158Enabled && !isGenesis)
   186→            {
   187→                if (_logger.IsTrace) Trace(address);
   188→                if (account.IsEmpty)
   189→                {
   190→                    PushTouch(address, account, spec, account.Balance.IsZero);
   191→                }
   192→            }
   193→
   194→            return inserted;
   195→
   196→            [MethodImpl(MethodImplOptions.NoInlining)]
   197→            void Debug(Address address, in ValueHash256 codeHash, Account account)
   198→                => _logger.Debug($"Update {address} C {account.CodeHash} -> {codeHash}");
   199→
   200→            [MethodImpl(MethodImplOptions.NoInlining)]
   201→            void Trace(Address address) => _logger.Trace($"Touch {address} (code hash)");
   202→
   203→            [DoesNotReturn, StackTraceHidden]
   204→            static Account ThrowIfNull(Address address)
   205→                => throw new InvalidOperationException($"Account {address} is null when updating code hash");
